", "new_str": "    public static void main(String[] args) throws Exception {
        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        long sessionGapMicros = params.getLong("sesssize", 600L) * 1_000_000L;

        Map<Long, Boolean> finishedJobs = new HashMap<>();
        for (JobEvent event : readJobEvents(jobInput)) {
            if (event.eventType == JOB_FINISH) {
                finishedJobs.put(event.jobId, true);
            }
        }

        Map<Long, List<Long>> submitTimestampsByJob = new HashMap<>();
        for (TaskEvent task : readTaskEvents(taskInput)) {
            if (task.eventType != TASK_SUBMIT) {
                continue;
            }
            submitTimestampsByJob.computeIfAbsent(task.jobId, ignored -> new ArrayList<>()).add(task.timestamp);
        }

        List<String> outputLines = new ArrayList<>();
        for (Map.Entry<Long, List<Long>> entry : submitTimestampsByJob.entrySet()) {
            long jobId = entry.getKey();
            if (!finishedJobs.containsKey(jobId)) {
                continue;
            }

            List<Long> times = entry.getValue();
            times.sort(Long::compare);

            int current = 0;
            int best = 0;
            long prev = Long.MIN_VALUE;
            for (long ts : times) {
                if (prev != Long.MIN_VALUE && ts - prev > sessionGapMicros) {
                    best = Math.max(best, current);
                    current = 0;
                }
                current++;
                prev = ts;
            }
            best = Math.max(best, current);

            outputLines.add("(" + jobId + "," + best + ")");
        }

        java.nio.file.Files.write(java.nio.file.Paths.get(outputPath), outputLines, StandardCharsets.UTF_8);
    }
