    private static final int TASK_SUBMIT = 0;
    private static final int JOB_FINISH = 4;

    public static void main(String[] args) throws Exception {
        Map<String, String> params = parseArgs(args);
        String taskInput = params.get("task_input");
        String jobInput = params.get("job_input");
        String outputPath = params.get("output");
        long sessionGapMicros = Long.parseLong(params.getOrDefault("sesssize", "600")) * 1_000_000L;

        Map<Long, Boolean> finishedJobs = new HashMap<>();
